```python
class MinHeap:
    def __init__(self):
        self.heap = []

    def _parent(self, i):
        return (i - 1) // 2

    def _left(self, i):
        return 2 * i + 1

    def _right(self, i):
        return 2 * i + 2

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def _heapify_up(self, i):
        """向上调整，用于插入后恢复堆性质"""
        while i > 0:
            p = self._parent(i)
            if self.heap[i] < self.heap[p]:
                self._swap(i, p)
                i = p
            else:
                break

    def _heapify_down(self, i):
        """向下调整，用于删除根后恢复堆性质"""
        n = len(self.heap)
        while True:
            smallest = i
            l = self._left(i)
            r = self._right(i)

            if l < n and self.heap[l] < self.heap[smallest]:
                smallest = l
            if r < n and self.heap[r] < self.heap[smallest]:
                smallest = r

            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break

    def insert(self, value):
        """插入元素"""
        self.heap.append(value)
        self._heapify_up(len(self.heap) - 1)

    def extract_min(self):
        """删除并返回最小元素（堆顶）"""
        if not self.heap:
            raise IndexError("extract_min from empty heap")
        if len(self.heap) == 1:
            return self.heap.pop()

        min_val = self.heap[0]
        # 将最后一个元素移到根
        self.heap[0] = self.heap.pop()
        # 向下调整
        self._heapify_down(0)
        return min_val

    def peek_min(self):
        """查看最小元素但不删除"""
        if not self.heap:
            raise IndexError("peek_min from empty heap")
        return self.heap[0]

    def is_empty(self):
        return len(self.heap) == 0

    def size(self):
        return len(self.heap)

    def __repr__(self):
        return f"MinHeap({self.heap})"


# 简单测试
if __name__ == "__main__":
    h = MinHeap()
    for x in [5, 3, 8, 1, 2]:
        h.insert(x)
        print("插入后:", h)

    print("最小元素:", h.peek_min())
    while not h.is_empty():
        print("extract_min:", h.extract_min())
```

说明要点：
- 使用数组 `self.heap` 存储堆，索引从 0 开始。
- 父节点：`(i - 1) // 2`，左子：`2*i + 1`，右子：`2*i + 2`。
- `insert`：在末尾插入，然后 `_heapify_up` 向上调整。
- `extract_min`：取出根，将最后一个元素移到根，然后 `_heapify_down` 向下调整。
- 时间复杂度：`insert` 和 `extract_min` 均为 O(log n)。

